<template><AuthLayout><h1 class="auth-heading">{{ $t('auth.changePasswordTitle') }}</h1><p class="auth-hint">{{ authState.me?.mustChangePassword ? $t('auth.changeRequiredHint') : $t('auth.changePasswordHint') }}</p><el-form label-position="top" @submit.prevent="submit"><el-form-item :label="$t('auth.currentPassword')"><el-input v-model="currentPassword" type="password" autocomplete="current-password" show-password /></el-form-item><el-form-item :label="$t('auth.newPassword')"><el-input v-model="newPassword" type="password" autocomplete="new-password" show-password /></el-form-item><el-form-item :label="$t('auth.confirmPassword')"><el-input v-model="confirmation" type="password" autocomplete="new-password" show-password /></el-form-item><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" /><el-button native-type="submit" type="primary" :loading="loading" class="submit">{{ $t('auth.changePassword') }}</el-button></el-form></AuthLayout></template>
<script setup lang="ts">
import { ref } from 'vue'; import { useRouter } from 'vue-router'; import { useI18n } from 'vue-i18n'; import { changePassword } from '../api/auth'; import { authState, refreshAuth } from '../auth/session'; import AuthLayout from '../layouts/AuthLayout.vue'
const router=useRouter(),{t}=useI18n(),currentPassword=ref(''),newPassword=ref(''),confirmation=ref(''),error=ref(''),loading=ref(false)
async function submit(){if(newPassword.value!==confirmation.value){error.value=t('auth.passwordMismatch');return}loading.value=true;error.value='';try{await changePassword(currentPassword.value,newPassword.value);await refreshAuth();await router.replace({name:'overview'})}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
</script>
